esqlQuery.esql:
TS metrics-supabase.metrics.otel-*
// Uncomment to ignore ephemeral mounts if your collector reports them.
// | WHERE attributes.fstype NOT IN ("tmpfs", "devtmpfs", "overlay", "squashfs")
// avail_bytes (not free_bytes) is the space actually usable by PostgreSQL, since it
// excludes root-reserved blocks. MIN()/MAX() take the worst-case headroom against the
// largest reported capacity for the mountpoint.
| STATS
    `Available Bytes` = MIN(LAST_OVER_TIME(node_filesystem_avail_bytes)),
    `Size Bytes` = MAX(LAST_OVER_TIME(node_filesystem_size_bytes))
  BY resource.attributes.supabase_project_ref, attributes.mountpoint, attributes.device
| WHERE `Size Bytes` > 0
| EVAL `Used %` = ROUND((1 - `Available Bytes` / `Size Bytes`) * 100, 1)
| EVAL `Available GB` = ROUND(`Available Bytes` / POW(1024, 3), 2)
// Tighten to 80 on small volumes, where 15% headroom is only a few hundred megabytes.
| WHERE `Used %` >= 85
// One row per mounted filesystem, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.mountpoint, " / ", attributes.device)
| SORT `Used %` DESC
